#include <windows.h>
#include <d3d11.h>
#include <dwmapi.h>
#include <tlhelp32.h>
#include <cstdint>
#include <cwchar>
#include "imgui.h"
#include "imgui_impl_win32.h"
#include "imgui_impl_dx11.h"
#pragma comment(lib, "d3d11.lib")
#pragma comment(lib, "d3dcompiler.lib")
#pragma comment(lib, "dwmapi.lib")

extern IMGUI_IMPL_API LRESULT ImGui_ImplWin32_WndProcHandler(HWND, UINT, WPARAM, LPARAM);

namespace off {
constexpr const wchar_t* exeName = L"game.exe";
constexpr const char* windowTitle = "Game";
constexpr uintptr_t entityList = 0x0;
constexpr uintptr_t localPlayer = 0x0;
constexpr uintptr_t viewMatrix = 0x0;
constexpr uintptr_t health = 0x0;
constexpr uintptr_t team = 0x0;
constexpr uintptr_t origin = 0x0;
constexpr uintptr_t stride = 0x8;
constexpr int maxEntities = 64;
constexpr float playerHeight = 72.f;
}

struct Vec3 { float x, y, z; };
struct Matrix { float m[16]; };

static HANDLE g_proc = nullptr;
static ID3D11Device* g_dev = nullptr;
static ID3D11DeviceContext* g_ctx = nullptr;
static IDXGISwapChain* g_sc = nullptr;
static ID3D11RenderTargetView* g_rtv = nullptr;

template <class T> T rd(uintptr_t a) { T v{}; ReadProcessMemory(g_proc, reinterpret_cast<LPCVOID>(a), &v, sizeof(T), nullptr); return v; }

static DWORD findPid(const wchar_t* name) {
    DWORD pid = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    CloseHandle(snap);
    return pid;
}

static uintptr_t findModule(DWORD pid, const wchar_t* name) {
    uintptr_t base = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, name)) { base = reinterpret_cast<uintptr_t>(me.modBaseAddr); break; }
    CloseHandle(snap);
    return base;
}

static bool w2s(const Vec3& p, const float* m, float w, float h, ImVec2& out) {
    float cw = m[12] * p.x + m[13] * p.y + m[14] * p.z + m[15];
    if (cw < 0.01f) return false;
    float cx = m[0] * p.x + m[1] * p.y + m[2] * p.z + m[3];
    float cy = m[4] * p.x + m[5] * p.y + m[6] * p.z + m[7];
    out = { w * 0.5f + cx / cw * w * 0.5f, h * 0.5f - cy / cw * h * 0.5f };
    return true;
}

static void makeRtv() {
    ID3D11Texture2D* bb = nullptr;
    g_sc->GetBuffer(0, IID_PPV_ARGS(&bb));
    g_dev->CreateRenderTargetView(bb, nullptr, &g_rtv);
    bb->Release();
}

static LRESULT CALLBACK wndProc(HWND h, UINT msg, WPARAM wp, LPARAM lp) {
    if (ImGui_ImplWin32_WndProcHandler(h, msg, wp, lp)) return 1;
    if (msg == WM_DESTROY) { PostQuitMessage(0); return 0; }
    return DefWindowProcA(h, msg, wp, lp);
}

int main() {
    DWORD pid = findPid(off::exeName);
    HWND game = FindWindowA(nullptr, off::windowTitle);
    if (!pid || !game) return 1;
    g_proc = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    uintptr_t base = findModule(pid, off::exeName);
    if (!g_proc || !base) return 1;

    WNDCLASSEXA wc{ sizeof(wc), CS_HREDRAW | CS_VREDRAW, wndProc, 0, 0, GetModuleHandleA(nullptr) };
    wc.lpszClassName = "esp_overlay";
    RegisterClassExA(&wc);
    HWND hwnd = CreateWindowExA(WS_EX_TOPMOST | WS_EX_TRANSPARENT | WS_EX_LAYERED | WS_EX_TOOLWINDOW, wc.lpszClassName, "",
                                WS_POPUP, 0, 0, 1, 1, nullptr, nullptr, wc.hInstance, nullptr);
    SetLayeredWindowAttributes(hwnd, 0, 255, LWA_ALPHA);
    MARGINS margins{ -1 };
    DwmExtendFrameIntoClientArea(hwnd, &margins);

    DXGI_SWAP_CHAIN_DESC sd{};
    sd.BufferCount = 2;
    sd.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    sd.OutputWindow = hwnd;
    sd.SampleDesc.Count = 1;
    sd.Windowed = TRUE;
    sd.SwapEffect = DXGI_SWAP_EFFECT_DISCARD;
    if (FAILED(D3D11CreateDeviceAndSwapChain(nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr, 0, nullptr, 0, D3D11_SDK_VERSION,
                                             &sd, &g_sc, &g_dev, nullptr, &g_ctx))) return 1;
    makeRtv();
    ShowWindow(hwnd, SW_SHOWNOACTIVATE);

    ImGui::CreateContext();
    ImGui::GetIO().ConfigFlags |= ImGuiConfigFlags_NoMouse;
    ImGui::GetIO().IniFilename = nullptr;
    ImGui_ImplWin32_Init(hwnd);
    ImGui_ImplDX11_Init(g_dev, g_ctx);

    int w = 0, h = 0;
    for (bool running = true; running && IsWindow(game) && !(GetAsyncKeyState(VK_END) & 1);) {
        MSG msg;
        while (PeekMessageA(&msg, nullptr, 0, 0, PM_REMOVE)) {
            TranslateMessage(&msg);
            DispatchMessageA(&msg);
            if (msg.message == WM_QUIT) running = false;
        }
        RECT rc; GetClientRect(game, &rc);
        POINT tl{ 0, 0 }; ClientToScreen(game, &tl);
        SetWindowPos(hwnd, HWND_TOPMOST, tl.x, tl.y, rc.right, rc.bottom, SWP_NOACTIVATE);
        if (rc.right != w || rc.bottom != h) {
            w = rc.right; h = rc.bottom;
            g_rtv->Release();
            g_sc->ResizeBuffers(0, w, h, DXGI_FORMAT_UNKNOWN, 0);
            makeRtv();
        }

        ImGui_ImplDX11_NewFrame();
        ImGui_ImplWin32_NewFrame();
        ImGui::NewFrame();
        ImDrawList* dl = ImGui::GetBackgroundDrawList();

        Matrix vm = rd<Matrix>(base + off::viewMatrix);
        uintptr_t local = rd<uintptr_t>(base + off::localPlayer);
        int myTeam = rd<int>(local + off::team);
        for (int i = 0; i < off::maxEntities; ++i) {
            uintptr_t e = rd<uintptr_t>(base + off::entityList + i * off::stride);
            if (!e || e == local) continue;
            int hp = rd<int>(e + off::health);
            if (hp <= 0 || hp > 100 || rd<int>(e + off::team) == myTeam) continue;
            Vec3 feet = rd<Vec3>(e + off::origin);
            Vec3 head{ feet.x, feet.y, feet.z + off::playerHeight };
            ImVec2 sf, sh;
            if (!w2s(feet, vm.m, float(w), float(h), sf) || !w2s(head, vm.m, float(w), float(h), sh)) continue;
            float bh = sf.y - sh.y, bw = bh * 0.5f, x = sh.x - bw * 0.5f, frac = hp / 100.f;
            dl->AddRect({ x, sh.y }, { x + bw, sf.y }, IM_COL32(255, 60, 60, 255), 0.f, 0, 1.5f);
            dl->AddRectFilled({ x - 6, sh.y }, { x - 3, sf.y }, IM_COL32(0, 0, 0, 180));
            dl->AddRectFilled({ x - 6, sf.y - bh * frac }, { x - 3, sf.y }, IM_COL32(int(255 * (1 - frac)), int(255 * frac), 0, 255));
        }

        ImGui::Render();
        const float clear[4]{ 0, 0, 0, 0 };
        g_ctx->OMSetRenderTargets(1, &g_rtv, nullptr);
        g_ctx->ClearRenderTargetView(g_rtv, clear);
        ImGui_ImplDX11_RenderDrawData(ImGui::GetDrawData());
        g_sc->Present(1, 0);
    }

    ImGui_ImplDX11_Shutdown();
    ImGui_ImplWin32_Shutdown();
    ImGui::DestroyContext();
    g_rtv->Release(); g_sc->Release(); g_ctx->Release(); g_dev->Release();
    CloseHandle(g_proc);
    DestroyWindow(hwnd);
    return 0;
}
